// Inline a minified IIFE of @patterkit/runtime into an ops module, so runExportHtml can produce a SINGLE
// self-contained playable HTML file with no external <script src>. Bundled HERE, runtime alone: the
// shared browser drop-in (patterplay.min.js, built by play-helpers) carries the helpers too, whose
// inspector and Live Link code the export never runs and whose `href=` / URL strings would trip the
// export's self-containment guard. Run after the runtime is built (the root build orders
// @patterkit/runtime before @patterkit/ops). Commit the generated file.
import { writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, resolve } from "node:path";
import { build } from "esbuild";

const here = dirname(fileURLToPath(import.meta.url));
const out = resolve(here, "../src/playable-runtime.ts");
const result = await build({
  stdin: { contents: 'export * from "@patterkit/runtime";', resolveDir: resolve(here, ".."), loader: "js" },
  bundle: true,
  write: false,
  format: "iife",
  globalName: "Patterplay",
  platform: "browser",
  minify: true,
  legalComments: "none",
});
const js = result.outputFiles[0].text;
const banner = "// GENERATED by scripts/gen-runtime-blob.mjs: @patterkit/runtime bundled as a minified IIFE (runtime alone).\n" +
  "// Inlined so runExportHtml can build a single self-contained HTML file.\n" +
  "// Do not edit by hand; re-run `node scripts/gen-runtime-blob.mjs` after a runtime change.\n";
writeFileSync(out, `${banner}export const PLAYABLE_RUNTIME_JS = ${JSON.stringify(js)};\n`);
console.log(`wrote ${out} (${js.length} bytes of runtime)`);
